#!/usr/bin/env python3
"""Author the reviewed documentation map. Read-only with respect to app source."""
from pathlib import Path
import csv,hashlib,json,re
ROOT=Path(__file__).resolve().parents[1];SRC=Path('/workspace/supernova-source-0138')
SHA='b3504c2c4b1725f3070416d14b63e53ae1db3d74';BASE='https://github.com/heretoecode/Supernova/blob/'+SHA+'/'
def source(owner,needle=''):
 files=list((SRC/'src/main/java').rglob(owner+'.java'));assert len(files)==1,owner
 f=files[0];lines=f.read_text().splitlines();line=next((i+1 for i,x in enumerate(lines) if needle and needle in x),1)
 return '['+owner+('.'+needle if needle else '')+']('+BASE+f.relative_to(SRC).as_posix()+'#L'+str(line)+')'
areas={}
def add(name,title,body,owners):
 areas[name]=title
 text='# '+title+'\n\nSource baseline: signed 0.138 `'+SHA+'`. Evidence below is **VERIFIED static source** unless expressly attributed to native CI evidence or **UNKNOWN**. No device-navigation test was run. Stable IDs describe surfaces; generated SITE/FOCUS IDs identify exact source lines.\n\n'+body+'\n\n## Source owners and exact option appendix\n\n'+ '\n'.join('- '+source(owner,needle) for owner,needle in owners)+'\n\n[Every matched display/choice expression in this area](../evidence/'+name+'-source-options.md) · [Full display sites](../evidence/display-sites.tsv) · [Focus branches](../evidence/focus-branches.tsv). Supplementary cross-area owners, including inherited utilities, appear in the full catalogue. Literal extraction does not establish visibility.\n'
 (ROOT/'areas'/ (name+'.md')).write_text(text)
